from typing import List

class Solution:
    def maxSum(self, nums: List[int], k: int, m: int) -> int:
        n = len(nums)
        prefix = [0] * (n + 1)

        for i, x in enumerate(nums):
            prefix[i + 1] = prefix[i] + x

        neg_inf = -10**18
        dp = [0] * (n + 1)

        for used in range(1, k + 1):
            new_dp = [neg_inf] * (n + 1)
            best = neg_inf

            for end in range(used * m, n + 1):
                start_limit = end - m
                best = max(best, dp[start_limit] - prefix[start_limit])
                new_dp[end] = max(new_dp[end - 1], prefix[end] + best)

            dp = new_dp

        return dp[n]
